HttpCallback 通道
以消费消息的app通道配置为HttpCallback，且callBackUrl为 http://host:8018/pushMessage 为例
代码示例 TunaHttpCbClientExample

public static void main(String[] args) {
    /*
        * 1. 创建 Client。参数说明：
        *  > port
        *  > 是否启用 SSL
        */
    TunaHttpCbClient client = new TunaHttpCbClient(8018, false);

    // 2. 创建 消息处理 Handler
    HttpCbMessageHandler messageHandler = new HttpCbMessageHandler<HttpCbMessage, Void>() {

        /**
            * 应用密钥
            */
        public String getSignKey() {
            return "your appSecret";
        }

        /**
            * 为了防止消息篡改，开放平台推送的数据包含签名信息。
            * 字段名为 _aop_signature，假设值为 serverSign。
            * 
            * 接收到消息后，SDK 首先会使用秘钥对接收到的内容进行签名，
            * 假设值为 clientSign。
            *
            * 1. 若 serverSign 与 clientSign 相同，则直接调用 {@link #onMessage(Object)} 方法。
            * 2. 若 serverSign 与 clientSign 不同，则调用该方法。若该方法返回 true，则继续
            *     调用 {@link #onMessage(Object)} 方法；否则直接返回状态码 401。
            */
        public boolean continueOnSignatureValidationFailed(String clientSign, String serverSign) {
            return false;
        }

        /**
            * 消费消息。
            * @throws MessageProcessException 消息消费不成功，如未达重试次数上限，开放平台将会择机重发消息
            */
        public Void onMessage(HttpCbMessage message) throws MessageProcessException {
            System.out.println("message: " + message);
            // 真正的业务逻辑在这。如果消费失败或异常，请抛出 MessageProcessException 异常
            try {
                boolean ret = doSth();
                if(ret) {
                    throw new MessageProcessException("xxx");
                }
            } catch(Exception e) {
                throw new MessageProcessException("xxx");
            }
            return null;
        }
    };
    // 注册 Handler
    client.registerMessageHandler("/pushMessage", messageHandler);

    // 3. 启动 Client
    client.start();

    // 4. 在应用关闭时，关闭客户端
    // client.shutdown();
}


WebSocket  通道
以消费消息的app通道配置为WebSocket为例子 
代码示例 TunaWebSocketClientExample

public static void main(String[] args) {
    /*
     * 开放平台1688环境
     */
    String url = "ws://message.1688.com/websocket";
    /**
     * 您的 AppKey
     */
    String appKey = "yourAppKey";
    /**
     * 您的应用秘钥
     */
    String secret = "yourSecret";   
    /**
     * 您客户端设置的接收线程池大小 默认为虚拟机内核数*40 用户可以自行修改
     */
    int threadNum = 160;    

    /**
     * 1. 创建 Client，如果不传入threadNum参数的话，client将使用默认线程数
     */
    TunaWebSocketClient client = new TunaWebSocketClient(appKey, secret, url);
    /**
     * 2. 创建 消息处理 Handler
     */
    WebSocketMessageHandler tunaMessageHandler = new WebSocketMessageHandler() {
        /**
         * 消费消息。
         * 
         */
        public boolean onMessage(WebSocketMessage message) throws MessageProcessException {
            boolean success = true;
            /**
             * 服务端推送的消息分为2种，
             * 业务数据：SERVER_PUSH
             * 系统消息：SYSTEM，如 appKey 与 secret 不匹配等，一般可忽略
             */
            if(WebSocketMessageType.SERVER_PUSH.name().equals(message.getType())) {
                try {
                    /**
                     * json串
                     */
                    System.out.println("message: " + message);
                } catch (Exception e) {

                }
            }
            /**
             * 只能返回true，否则会导致消息一直处于发送中状态
             */
            return success;
        }
    };
    client.setTunaMessageHandler(tunaMessageHandler);

    /**
     * 3. 启动 Client
     */
    client.connect();

    /**
     * 4. 在应用关闭时，关闭客户端
     */
    // client.shutdown();
}


